import { useState } from "react";
import "../styles/ChatMessage.css";

export function ChatMessage() {
  const [messages] = useState([
    { id: 1, text: "Hello! I'm your AI assistant. 💙", isUser: false, timestamp: "10:00 AM" },
    { id: 2, text: "Hi! Can you help me with my English?", isUser: true, timestamp: "10:01 AM" },
    { id: 3, text: "Of course! Let's practice together. ✨", isUser: false, timestamp: "10:01 AM" },
  ]);

  return (
    <div className="messages-preview">
      {messages.map((msg) => (
        <div
          key={msg.id}
          className={`message ${msg.isUser ? "user-message" : "ai-message"}`}
        >
          <div className="message-avatar">
            <span>{msg.isUser ? "U" : "AI"}</span>
          </div>

          <div className="message-content">
            <div className="message-bubble">{msg.text}</div>
            {msg.timestamp && (
              <div className="message-timestamp">{msg.timestamp}</div>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
